                max_y[j] = max(max_y[j], matrix[i][j])
        ans = []
        for i in range(m):
            for j in range(n):
                if matrix[i][j] == min_x[i] and matrix[i][j] == max_y[j]:
                    ans.append(matrix[i][j])
        return ans
